const data = context.panel.data.series[0];
if (!data || !data.fields || data.fields.length === 0) {
  return { title: { text: 'No data', left: 'center', top: 'center', textStyle: { color: '#ccc', fontSize: 16 } } };
}

const agentField = data.fields.find(f => f.name === 'agent_type');
const bucketField = data.fields.find(f => f.name === 'bucket');
const countField = data.fields.find(f => f.name === 'count');

if (!agentField || !bucketField || !countField) {
  return { title: { text: 'Missing fields', left: 'center', top: 'center', textStyle: { color: '#ccc' } } };
}

const agents = [...new Set(agentField.values)];
const buckets = [...new Set(bucketField.values)].sort((a, b) => a - b);
const bucketLabels = buckets.map(b => b + 's');

const series = agents.map(agent => {
  const agentData = buckets.map(bucket => {
    for (let i = 0; i < agentField.values.length; i++) {
      if (agentField.values[i] === agent && bucketField.values[i] === bucket) {
        return countField.values[i];
      }
    }
    return 0;
  });
  return {
    name: agent,
    type: 'bar',
    stack: 'total',
    emphasis: { focus: 'series' },
    data: agentData
  };
});

return {
  tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } },
  legend: { data: agents, bottom: 0, textStyle: { color: '#ccc' } },
  grid: { left: 50, right: 20, top: 30, bottom: 40 },
  xAxis: { type: 'category', data: bucketLabels, axisLabel: { color: '#ccc' }, name: 'Duration', nameTextStyle: { color: '#999' } },
  yAxis: { type: 'value', axisLabel: { color: '#ccc' }, name: 'Count', nameTextStyle: { color: '#999' } },
  series: series
};

const data = context.panel.data.series[0];
if (!data || !data.fields || data.fields.length === 0) {
  return { title: { text: 'No data', left: 'center', top: 'center', textStyle: { color: '#ccc', fontSize: 16 } } };
}

const dayField = data.fields.find(f => f.name === 'dow');
const hourField = data.fields.find(f => f.name === 'hour');
const countField = data.fields.find(f => f.name === 'count');

if (!dayField || !hourField || !countField) {
  return { title: { text: 'Missing fields', left: 'center', top: 'center', textStyle: { color: '#ccc' } } };
}

const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const hours = Array.from({length: 24}, (_, i) => i + ':00');

const heatData = [];
let maxVal = 0;
for (let i = 0; i < dayField.values.length; i++) {
  const val = countField.values[i] || 0;
  heatData.push([hourField.values[i], dayField.values[i], val]);
  if (val > maxVal) maxVal = val;
}

return {
  tooltip: {
    position: 'top',
    formatter: function(p) {
      return days[p.value[1]] + ' ' + hours[p.value[0]] + ': ' + p.value[2] + ' commands';
    }
  },
  grid: { left: 60, right: 40, top: 20, bottom: 40 },
  xAxis: { type: 'category', data: hours, splitArea: { show: true }, axisLabel: { color: '#ccc', interval: 2 } },
  yAxis: { type: 'category', data: days, splitArea: { show: true }, axisLabel: { color: '#ccc' } },
  visualMap: {
    min: 0,
    max: Math.max(maxVal, 1),
    calculable: true,
    orient: 'horizontal',
    left: 'center',
    bottom: 0,
    inRange: { color: ['#1a1a2e', '#533483', '#e94560', '#f5af19'] },
    textStyle: { color: '#ccc' }
  },
  series: [{
    name: 'Commands',
    type: 'heatmap',
    data: heatData,
    label: { show: false },
    emphasis: {
      itemStyle: { shadowBlur: 10, shadowColor: 'rgba(0,0,0,0.5)' }
    }
  }]
};
